DROP TABLE IF EXISTS `assets`;
CREATE TABLE `assets` (
  `id` varchar(50) NOT NULL,
  `image` longtext DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `brand` varchar(100) NOT NULL,
  `model` varchar(100) NOT NULL,
  `asset_number` varchar(100) DEFAULT '',
  `serial_number` varchar(100) NOT NULL,
  `assigned_personnel_id` varchar(50) DEFAULT '',
  `assigned_personnel_name` varchar(255) DEFAULT '',
  `department` varchar(150) NOT NULL,
  `location` varchar(255) NOT NULL,
  `room` varchar(150) NOT NULL,
  `status` enum('ใช้งาน','ชำรุด','รอจำหน่าย','จำหน่าย') NOT NULL DEFAULT 'ใช้งาน',
  `disposed_date` varchar(50) DEFAULT NULL,
  `disposed_reason` text DEFAULT NULL,
  `last_inspected_date` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `serial_number` (`serial_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

