DROP TABLE IF EXISTS `inspection_history`;
CREATE TABLE `inspection_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `asset_id` varchar(50) NOT NULL,
  `date` varchar(50) NOT NULL,
  `inspector_name` varchar(255) NOT NULL,
  `old_status` varchar(50) NOT NULL,
  `new_status` varchar(50) NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `asset_id` (`asset_id`),
  CONSTRAINT `inspection_history_ibfk_1` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `inspection_history` (`id`, `asset_id`, `date`, `inspector_name`, `old_status`, `new_status`, `notes`, `created_at`) VALUES
